"""版本号解析与比较。

Windows 产品的版本号习惯是 ``major.minor.build.revision`` 四段十进制，
末尾段可以省略（省略视作 0），并且允许 ``1.2.3.4-beta.1`` 这样的预发布标签。

比较一律按**十进制整数**逐段进行：``1.10.0`` 高于 ``1.9.0``。
"""

_STRIP = "vV"
_SEGMENTS = 4


def normalize(text):
    """去掉可选的 ``v`` 前缀与首尾空白。"""
    value = str(text).strip()
    while value[:1] in _STRIP:
        value = value[1:]
    return value


def split_version(text):
    """把版本号拆成 ``(数字部分, 预发布标签)``。"""
    value = normalize(text)
    if "-" in value:
        numbers, prerelease = value.split("-", 1)
    else:
        numbers, prerelease = value, ""
    return numbers, prerelease.strip()


def parse_version(text):
    """把版本号解析成四个十进制整数段。

    不足四段的补 0；段内出现非十进制字符时按 0 处理。
    """
    numbers, _prerelease = split_version(text)
    segments = []
    for piece in numbers.split("."):
        piece = piece.strip()
        segments.append(int(piece) if piece.isdigit() else 0)
    while len(segments) < _SEGMENTS:
        segments.append(0)
    return tuple(segments[:_SEGMENTS])


def _compare_prerelease(left, right):
    """比较两个预发布标签。

    空标签（正式版）高于任何预发布标签；否则按点分标识符比较，
    纯数字标识符按数值比较且低于非数字标识符。
    """
    if left == right:
        return 0
    if not left:
        return 1
    if not right:
        return -1
    left_parts = left.split(".")
    right_parts = right.split(".")
    for lp, rp in zip(left_parts, right_parts):
        if lp == rp:
            continue
        left_num = lp.isdigit()
        right_num = rp.isdigit()
        if left_num and right_num:
            return 1 if int(lp) > int(rp) else -1
        if left_num:
            return -1
        if right_num:
            return 1
        return 1 if lp > rp else -1
    if len(left_parts) == len(right_parts):
        return 0
    return 1 if len(left_parts) > len(right_parts) else -1


def compare_versions(left, right):
    """比较两个版本号。

    返回 ``-1`` / ``0`` / ``1``。数字段按十进制整数逐段比较，
    不足四段补 0；预发布版本低于同号的正式版。
    """
    left_segments = parse_version(left)
    right_segments = parse_version(right)
    if left_segments != right_segments:
        return 1 if left_segments > right_segments else -1
    _left_numbers, left_pre = split_version(left)
    _right_numbers, right_pre = split_version(right)
    return _compare_prerelease(left_pre, right_pre)


def is_upgrade(current, candidate):
    """``candidate`` 是否严格高于 ``current``。"""
    return compare_versions(candidate, current) > 0

"""执行计划中的动作，并维护清单。

写入采用「同目录临时文件 + 原子替换」：目标位置要么是旧内容，要么是新内容，
不会出现半个文件。

Windows 上别的进程可能正打开着某个目标文件。这种情况下替换会失败，
但整次事务**不该**因此崩溃：该文件保持旧内容不动，记进结果的
``deferred`` 与清单的 ``pending_replace``，等占用解除后对同一份计划
再次执行即可完成替换。

其它无法推迟的失败（例如目标位置被同名目录占据）必须让整次事务
**整体回滚**：已覆盖的文件逐字节恢复、新建的文件删除、清单回到
执行前的状态，然后抛 :class:`~winstall.errors.ApplyFailed`。
"""

import os
import shutil
import tempfile
from collections import namedtuple

from . import layout, manifest, planner
from .errors import ApplyFailed

ApplyResult = namedtuple("ApplyResult", "operation product version applied deferred")

TMP_SUFFIX = ".winstall-part"
_BACKUP_SUFFIX = ".winstall-backup"


def _is_sharing_violation(exc):
    """这个错误是否意味着「文件正被别的进程占用」（可以推迟）。"""
    if isinstance(exc, PermissionError):
        return True
    winerror = getattr(exc, "winerror", None)
    # ERROR_SHARING_VIOLATION(32) / ERROR_LOCK_VIOLATION(33) / ERROR_ACCESS_DENIED(5)
    return winerror in (5, 32, 33)


def _ensure_parent(path):
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)


def _put_file(source, destination):
    """把 ``source`` 放到 ``destination``（原子替换）。

    临时文件落在目标同目录；替换成功或失败都不会留下临时文件。
    """
    temporary = destination + TMP_SUFFIX
    try:
        shutil.copyfile(source, temporary)
        os.replace(temporary, destination)
    finally:
        if os.path.isfile(temporary):
            try:
                os.remove(temporary)
            except OSError:
                pass


def _delete_file(path):
    if os.path.isfile(path):
        os.remove(path)


def _remove_empty_parents(root, path):
    """把 ``path`` 之下空掉的父目录一路清到 ``root`` 为止。"""
    root = os.path.abspath(root)
    current = os.path.dirname(os.path.abspath(path))
    while current.startswith(root) and current != root:
        try:
            os.rmdir(current)
        except OSError:
            break
        current = os.path.dirname(current)


def _snapshot(path, backup_dir, relpath):
    """把 ``path`` 的当前内容备份到 ``backup_dir`` 下，返回备份路径或 ``None``。"""
    if not os.path.isfile(path):
        return None
    backup = os.path.join(backup_dir, relpath.replace("/", os.sep) + _BACKUP_SUFFIX)
    _ensure_parent(backup)
    shutil.copyfile(path, backup)
    return backup


def _rollback(plan, backups, created, data_before):
    """把整次事务恢复到执行前的状态。

    * 被覆盖的文件从备份逐字节恢复
    * 本次新建的文件删除
    * 清单恢复到执行前的内容
    * 清掉所有临时 / 备份文件
    """
    payload = layout.payload_dir(plan.root, plan.product)
    for relpath, backup in backups.items():
        target = os.path.join(payload, relpath.replace("/", os.sep))
        try:
            if backup is None:
                if os.path.isfile(target):
                    os.remove(target)
                    _remove_empty_parents(payload, target)
            else:
                _ensure_parent(target)
                shutil.copyfile(backup, target)
        except OSError:
            pass
    for path in created:
        try:
            if os.path.isfile(path):
                os.remove(path)
                _remove_empty_parents(payload, path)
        except OSError:
            pass
    try:
        manifest.write_manifest(plan.root, data_before)
    except OSError:
        pass


def _flush_pending(plan, data, pending):
    """占用解除后，完成清单里 ``pending_replace`` 记录的文件替换。

    源文件按本次计划的 ``files`` 映射查找；仍然被占用的留在
    ``pending`` 里继续等待。返回本轮完成的相对路径列表。
    """
    sources = {}
    for action in plan.actions:
        if action.kind == "write":
            sources[action.relpath] = action.source
    payload = layout.payload_dir(plan.root, plan.product)
    done = []
    for relpath in list(pending):
        source = sources.get(relpath)
        if source is None or not os.path.isfile(source):
            continue
        target = os.path.join(payload, relpath.replace("/", os.sep))
        try:
            _ensure_parent(target)
            _put_file(source, target)
        except OSError as exc:
            if _is_sharing_violation(exc):
                continue
            raise
        pending.remove(relpath)
        done.append(relpath)
    return done


def apply_transaction(plan):
    """顺序执行 ``plan`` 中的动作，然后更新清单。

    被占用的文件记进 ``deferred`` 与清单的 ``pending_replace``；
    不可推迟的失败整体回滚后抛 :class:`ApplyFailed`。
    """
    payload = layout.payload_dir(plan.root, plan.product)
    data_before = manifest.read_manifest(plan.root)
    entry_before = manifest.get_product(data_before, plan.product)
    pending = list((entry_before or {}).get("pending_replace") or [])

    backups = {}
    created = []
    applied = []
    deferred = []
    backup_dir = tempfile.mkdtemp(prefix="winstall-")
    try:
        for action in plan.actions:
            target = planner.destination(plan, action)
            if action.kind == "write":
                try:
                    _ensure_parent(target)
                    existed = os.path.isfile(target)
                    if existed and action.relpath not in backups:
                        backups[action.relpath] = _snapshot(target, backup_dir,
                                                            action.relpath)
                    _put_file(action.source, target)
                except OSError as exc:
                    if _is_sharing_violation(exc) and os.path.isfile(target):
                        # 文件被占用：保持旧内容不动，推迟到下一次执行。
                        deferred.append(action.relpath)
                        continue
                    raise ApplyFailed(
                        action, "cannot apply %s: %s" % (action.relpath, exc)) from exc
                if not existed:
                    created.append(target)
                applied.append(action.relpath)
            elif action.kind == "remove":
                try:
                    if os.path.isfile(target) and action.relpath not in backups:
                        backups[action.relpath] = _snapshot(target, backup_dir,
                                                            action.relpath)
                    _delete_file(target)
                except OSError as exc:
                    if _is_sharing_violation(exc):
                        deferred.append(action.relpath)
                        continue
                    raise ApplyFailed(
                        action, "cannot remove %s: %s" % (action.relpath, exc)) from exc
                applied.append(action.relpath)
            else:
                raise ValueError("unknown action: %r" % (action.kind,))
    except ApplyFailed:
        _rollback(plan, backups, created, data_before)
        raise
    except Exception:
        _rollback(plan, backups, created, data_before)
        raise
    finally:
        shutil.rmtree(backup_dir, ignore_errors=True)

    # 占用解除后，对同一份计划再次执行时，把上一轮推迟的文件补齐。
    try:
        finished = _flush_pending(plan, data_before, pending)
    except OSError as exc:
        _rollback(plan, backups, created, data_before)
        raise ApplyFailed(None, "cannot finish pending replacements: %s" % exc) from exc
    applied.extend(rel for rel in finished if rel not in applied)

    data = manifest.read_manifest(plan.root)
    still_pending = sorted(set(pending) | set(deferred))
    if plan.operation == planner.INSTALL:
        manifest.set_product(data, plan.product, plan.version, plan.files, still_pending)
    else:
        if still_pending:
            entry = manifest.get_product(data, plan.product) or {}
            manifest.set_product(data, plan.product,
                                 entry.get("version") or plan.version,
                                 entry.get("files") or [], still_pending)
        else:
            manifest.drop_product(data, plan.product)
    manifest.write_manifest(plan.root, data)

    return ApplyResult(plan.operation, plan.product, plan.version,
                       tuple(applied), tuple(deferred))
